# GENERATED by plugin-cursor/scripts/compose.sh — edit core/ or plugin-claude/ then re-compose
"""Pipeline report — Markdown renderer (PIPELINE.md)."""

from html import escape


# v2 lifecycle state emoji mapping
STAGE_EMOJI = {
    # Scrum lifecycle states
    "INCEPTION": "📋", "SPRINT_PLANNING": "📋", "SPRINT_EXECUTION": "🏗️",
    "SPRINT_REVIEW": "🛡️", "SPRINT_RETRO": "🔄", "SPRINT_CLOSE": "📊",
    "RELEASE": "🚀",
    # Kanban lifecycle states
    "DISCOVER": "🔍", "READY": "📋", "EXECUTION": "🏗️", "REVIEW": "🛡️",
    # Shared
    "COMPLETE": "✅",
}

def _md_header(s: dict) -> str:
    proj = s["project"]
    pipe = s["pipeline"]
    sprint = s.get("sprint")
    sprint_info = ""
    if sprint:
        goal = sprint.get("sprint_goal") or "active"
        sprint_info = f" | Sprint {sprint['current_sprint']}: {goal}"
    mode = pipe.get("build_mode", "scrum").capitalize()
    return f"""# PIPELINE — {proj['name']}

> Generated: {s['generated_at_display']}
> Engagement: {proj['engagement'].capitalize()} | Mode: {mode} | Stack: {proj['stack'] or '—'} | Elapsed: {pipe['total_elapsed']} | State: {pipe['lifecycle_state']}{sprint_info}

---
"""


def _md_progress(s: dict) -> str:
    lines = ["## Lifecycle Progress\n"]
    pipe = s["pipeline"]

    for stage in pipe.get("stages", []):
        name = stage["name"]
        if name == "COMPLETE":
            continue
        emoji = STAGE_EMOJI.get(name, "○")
        status = stage["status"]

        if status == "complete":
            marker = "✅"
            label = f"Complete in {stage['duration']}"
        elif status == "active":
            marker = "●"
            label = f"**▶ In Progress** ⏱ {stage['duration']}"
        else:
            marker = "○"
            label = "Pending"

        lines.append(f"### {marker} {emoji} {name} — {label}\n")
        lines.append("")

    return "\n".join(lines)


def _md_sprint_progress(s: dict) -> str:
    sprint = s.get("sprint")
    if not sprint:
        return ""

    STATUS_ICON = {"complete": "✅", "active": "●", "planned": "○"}

    lines = ["## Sprint Progress\n"]
    lines.append("| Sprint | Stories | Velocity | DoD Compliance | Status |")
    lines.append("|--------|---------|----------|---------------|--------|")

    for sp in sprint.get("sprints", []):
        icon = STATUS_ICON.get(sp["status"], "○")
        status_display = sp["status"].replace("_", " ").capitalize()
        velocity = sp.get("velocity", "—")
        dod = sp.get("dod_compliance", "—")
        if isinstance(dod, (int, float)) and dod > 0:
            dod = f"{dod:.0%}" if dod <= 1 else f"{dod}%"
        lines.append(
            f"| Sprint {sp['number']} "
            f"| {sp['stories']} | {velocity} | {dod} "
            f"| {icon} {status_display} |"
        )

    completed = sprint["sprints_completed"]
    total = sprint.get("total_sprints") or "?"
    current = sprint["current_sprint"]
    goal = sprint.get("sprint_goal") or "in progress"

    lines.append(
        f"\n**Overall:** {completed}/{total} sprints complete"
        f" — Sprint {current}: {goal}\n"
    )
    return "\n".join(lines)


def _md_agent_metrics(s: dict) -> str:
    """Render agent metrics from story-scoped receipt data."""
    receipts = s.get("receipts_normalized", [])
    if not receipts:
        return ""

    lines = [
        "## Agent Metrics\n",
        "| Story | Role | Backend | Artifacts | Key Artifacts |",
        "|-------|------|---------|-----------|---------------|",
    ]

    for r in receipts:
        role = r.get("role", "unknown")
        backend = r.get("backend", "unknown")
        story_id = r.get("story_id", "?")
        arts = ", ".join(r.get("key_artifacts", [])[:3])
        count = r.get("artifacts_count", 0)
        if count > 3:
            arts += f" +{count - 3} more"
        lines.append(f"| {story_id} | {role} | {backend} | {count} | {arts or '—'} |")

    lines.append(f"\n**Total receipts:** {len(receipts)}\n")
    return "\n".join(lines)


def _md_findings(s: dict) -> str:
    findings = s["findings"]
    summary = findings["summary"]
    fixed = findings["fixed"]
    items = findings["items"]
    total = sum(summary.values())

    if total == 0 and not items:
        return ""

    SEV_ICON = {"critical": "🔴", "high": "🟠", "medium": "🟡", "low": "🟢"}
    lines = ["## Quality & Findings\n"]

    # Summary table
    lines.append("| Severity | Found | Fixed | Open |")
    lines.append("|----------|-------|-------|------|")
    for sev in ("critical", "high", "medium", "low"):
        found = summary.get(sev, 0)
        fx = fixed.get(sev, 0)
        # Count from items for more accuracy
        found_items = len([i for i in items if i["severity"] == sev])
        fixed_items = len([i for i in items if i["severity"] == sev and i["status"] == "fixed"])
        open_items = len([i for i in items if i["severity"] == sev and i["status"] == "open"])
        # Use max of summary counts and item counts
        found_display = max(found, found_items)
        fixed_display = max(fx, fixed_items)
        open_display = found_display - fixed_display if found_display > fixed_display else open_items
        icon = SEV_ICON[sev]
        lines.append(f"| {icon} {sev.upper()} | {found_display} | {fixed_display} | {open_display} |")
    lines.append("")

    # Individual items (open first, then fixed)
    open_items = [i for i in items if i["status"] == "open"]
    fixed_list = [i for i in items if i["status"] == "fixed"]

    if open_items:
        lines.append("### Open Findings\n")
        for item in open_items:
            icon = SEV_ICON.get(item["severity"], "⚪")
            ref = f" `{item['file_ref']}`" if item.get("file_ref") else ""
            lines.append(f"- {icon} **{item.get('id', '')}** {item['title']}{ref}")
        lines.append("")

    if fixed_list:
        lines.append(f"### Remediated ({len(fixed_list)} fixed)\n")
        for item in fixed_list[:10]:
            ref = f" (fixed by {item['fixed_by']})" if item.get("fixed_by") else ""
            lines.append(f"- ~~{item.get('id', '')} {item['title']}~~{ref}")
        if len(fixed_list) > 10:
            lines.append(f"- _...and {len(fixed_list) - 10} more_")
        lines.append("")

    return "\n".join(lines)


def _md_verification(s: dict) -> str:
    commands = s["verification"]["commands"]
    if not commands:
        return ""
    lines = [
        "## Verification Commands\n",
        "| Story | Role | Command | Exit | Summary |",
        "|-------|------|---------|------|---------|\n",
    ]
    for cmd in commands:
        icon = "✅" if str(cmd["exit_code"]) == "0" else "❌"
        lines.append(f"| {cmd.get('story_id', '?')} | {cmd.get('role', '?')} | `{cmd['command']}` | {icon} {cmd['exit_code']} | {cmd.get('summary', '')[:60]} |")
    lines.append("")
    return "\n".join(lines)


def _md_dod_summary(s: dict) -> str:
    dod = s.get("dod_summary")
    if not dod:
        return ""
    lines = ["## Definition of Done Summary\n"]

    inception = "✅ Approved" if dod.get("inception_gate") == "approved" else "⏳ Pending"
    lines.append(f"- **Inception Gate:** {inception}")

    total = dod.get("stories_total", 0)
    evaluated = dod.get("stories_evaluated", 0)
    passed = dod.get("stories_passed", 0)
    rate = dod.get("pass_rate", 0)
    lines.append(f"- **Stories:** {passed}/{evaluated} passed DoD ({rate:.0%}) out of {total} total")

    checks = dod.get("checks", {})
    if checks:
        lines.append("\n| Check | Pass | Fail | Skip |")
        lines.append("|-------|------|------|------|")
        for cid, counts in checks.items():
            lines.append(f"| {cid} | {counts.get('pass', 0)} | {counts.get('fail', 0)} | {counts.get('skip', 0)} |")

    lines.append("")
    return "\n".join(lines)


def _md_open_items(s: dict) -> str:
    items = s.get("open_items", [])
    if not items:
        return ""
    lines = ["## Open Items\n"]
    for item in items:
        desc = item.get("description", "")
        source = f" (from {item.get('source_story', '')})" if item.get("source_story") else ""
        lines.append(f"- {desc}{source}")
    lines.append("")
    return "\n".join(lines)


def _md_context_packages(s: dict) -> str:
    packages = s.get("context_packages", [])
    if not packages or all(p["status"] == "pending" for p in packages):
        return ""
    lines = ["## Brownfield Context Packages\n"]
    for pkg in packages:
        if pkg["status"] == "generated":
            lines.append(f"- ✅ **{pkg['name']}** ({pkg['date']})")
        else:
            lines.append(f"- ○ {pkg['name']} — not yet generated")
    lines.append("")
    return "\n".join(lines)


def _md_next_steps(s: dict) -> str:
    state = s["pipeline"]["lifecycle_state"]
    sprint = s.get("sprint")
    lines = ["## Next Steps\n"]

    if state == "INCEPTION":
        lines.append("- Inception in progress — establishing project foundation")
    elif state == "SPRINT_PLANNING":
        lines.append("- Sprint Planning — refining stories and selecting sprint backlog")
    elif state == "SPRINT_EXECUTION":
        if sprint:
            cur = sprint["current_sprint"]
            goal = sprint.get("sprint_goal") or "in progress"
            lines.append(f"- Sprint {cur} execution — {goal}")
        else:
            lines.append("- Sprint execution in progress")
    elif state == "SPRINT_REVIEW":
        lines.append("- Sprint Review — demo working software and evaluate DoD")
    elif state == "SPRINT_RETRO":
        lines.append("- Sprint Retrospective — inspect and adapt")
    elif state == "SPRINT_CLOSE":
        lines.append("- Sprint Close — decide: next sprint or release")
    elif state == "DISCOVER":
        lines.append("- Discover — reverse-engineering codebase for context packages")
    elif state == "READY":
        lines.append("- Ready — pull next ticket from backlog")
    elif state == "EXECUTION":
        lines.append("- Ticket execution in progress (Kanban)")
    elif state == "REVIEW":
        lines.append("- Ticket review — demo and collect feedback")
    elif state == "RELEASE":
        lines.append("- Release — full verification + production preparation")
    elif state == "COMPLETE":
        lines.append("- Pipeline complete ✅")
    else:
        lines.append("- Run `/synaptory` and describe what you want to build")

    lines.append("\n```")
    lines.append("status              — refresh this view")
    lines.append("/synaptory           — continue pipeline")
    if sprint:
        lines.append("next sprint         — advance to next sprint")
    lines.append("understand this codebase — (re)run brownfield analysis")
    lines.append("```\n")
    return "\n".join(lines)


def _md_sprint_detail(s: dict) -> str:
    detail = s.get("sprint_detail")
    if not detail:
        return ""

    header = detail["header"]
    board = detail["story_board"]
    dod = detail["dod_checklist"]
    summary = detail["summary"]

    STATUS_ICON = {
        "done": "✓", "review": "⚠", "in_progress": "↻",
        "blocked": "✗", "not_started": "○",
    }

    lines = []

    # ── Part 1: Sprint header
    lines.append(f"## Sprint {header['number']} Detail — {header['goal']}\n")
    meta_parts = []
    if header["dates"]:
        meta_parts.append(f"Dates: {header['dates']}")
    if header["capacity"]:
        meta_parts.append(f"Capacity: {header['capacity']}")
    if header["phase"]:
        meta_parts.append(f"Phase: {header['phase'].replace('_', ' ')}")
    if meta_parts:
        lines.append(f"> {' | '.join(meta_parts)}\n")

    # ── Part 2: Story board
    total = summary["stories_total"]
    done = summary["stories_done"] + summary["stories_review"]
    lines.append(f"### Story Board — {done}/{total} stories complete\n")
    lines.append("| ID | Title | Size | ACs | Tests | Findings | Status |")
    lines.append("|-----|-------|------|-----|-------|----------|--------|")

    for st in board:
        icon = STATUS_ICON.get(st["status"], "○")
        if st["acs_total"]:
            acs_str = f"{st['acs_met']}/{st['acs_total']}"
        elif not st.get("has_brd", True):
            acs_str = "N/A"
        else:
            acs_str = "—"
        tests_str = str(st["test_count"]) if st["test_count"] else "—"
        findings_str = "—"
        if st["findings_count"] > 0:
            highest = "🔴" if any(f["severity"] == "critical" for f in st["findings"]) else \
                      "🟠" if any(f["severity"] == "high" for f in st["findings"]) else "🟡"
            findings_str = f"{highest}{st['findings_count']}"
        status_display = {"done": "Done", "review": "Review", "in_progress": "In Progress",
                          "blocked": "Blocked", "not_started": "Not Started"}.get(st["status"], st["status"])
        lines.append(
            f"| {st['id']} | {st['title']} | {st['size'] or '—'} "
            f"| {acs_str} | {tests_str} | {findings_str} "
            f"| {icon} {status_display} |"
        )

    # Totals line
    lines.append(
        f"\n**Totals:** {summary['stories_done']} Done · "
        f"{summary['stories_review']} Review · "
        f"{summary['stories_in_progress']} In Progress · "
        f"{summary['stories_blocked']} Blocked"
    )
    if summary["must_completion"] > 0:
        lines.append(f"**Must stories:** {summary['must_completion']}% complete\n")
    else:
        lines.append("")

    # ── Part 3: AC drill-down (only for stories with findings)
    review_stories = [st for st in board if st["status"] == "review" and st["acs"]]
    if review_stories:
        lines.append("### AC Drill-Down (Stories with Findings)\n")
        for st in review_stories:
            lines.append(f"#### {st['id']} — {st['title']}  ⚠ Review\n")
            for ac in st["acs"]:
                if ac["status"] == "met":
                    lines.append(f"- ✓ **{ac['id']}** {ac['text']}")
                elif ac["status"] == "finding":
                    ref = f" — {ac['finding_ref']}" if ac["finding_ref"] else ""
                    lines.append(f"- ⚠ **{ac['id']}** {ac['text']}{ref}")
                    # Show the finding detail
                    for f in st["findings"]:
                        if f.get("id") == ac["finding_ref"]:
                            sev_icon = {"critical": "🔴", "high": "🟠", "medium": "🟡"}.get(f["severity"], "⚪")
                            lines.append(f"  - {sev_icon} {f['id']}: {f['title']}")
                else:
                    lines.append(f"- ○ **{ac['id']}** {ac['text']}")
            lines.append("")

    # ── Part 4: DoD checklist
    if dod:
        lines.append("### Definition of Done\n")
        DOD_ICON = {"met": "✅", "blocked": "⚠️", "pending": "○"}
        for item in dod:
            icon = DOD_ICON.get(item["status"], "○")
            lines.append(f"- {icon} {item['text']}")
        lines.append(
            f"\n**{summary.get('dod_met', 0)}/{summary.get('dod_total', 0)} met** · "
            f"{summary.get('dod_blocked', 0)} blocked\n"
        )

    return "\n".join(lines)


def _md_footer(s: dict) -> str:
    return (
        "\n---\n\n"
        f"_Generated by synaptory at {s['generated_at_display']}_  \n"
    )


def render_markdown(summary: dict) -> str:
    sections = [
        _md_header(summary),
        _md_progress(summary),
        _md_sprint_progress(summary),
        _md_sprint_detail(summary),
        _md_dod_summary(summary),
        _md_agent_metrics(summary),
        _md_findings(summary),
        _md_verification(summary),
        _md_open_items(summary),
        _md_context_packages(summary),
        _md_next_steps(summary),
        _md_footer(summary),
    ]
    return "\n".join(s for s in sections if s.strip())

